def _ensure_user2110(user_id, display_name=None):
    uid = (user_id or "default").strip()[:200] or "default"
    with _DB_LOCK_2110, _db2110() as c:
        row = c.execute("SELECT user_id FROM infinity_users_2110 WHERE user_id=?", (uid,)).fetchone()
