@app.post("/chat")
def _chat2110(req: _Chat2110):
    user=_ensure_user2110(req.user_id); cid=_conversation2110(user,req.conversation_id)
    _message2110(cid,user,"user",req.message)
    if req.execute:
        plan=_plan2110(req.message,user)
        if plan["approval_required"] and not req.authorized:
            reply="I can prepare this action, but it requires scoped authority before an external side effect."
            execution={"status":"awaiting_authority","plan":plan}
        else:
            mid=_create_mission2110(user,req.message,plan,plan["approval_required"] and not req.authorized)
            if req.authorized or not plan["approval_required"]:
                _run_mission2110(mid,user,req.message,plan,req.authorized)
            reply="Mission created. I will report only the result actually produced by the execution layer."
            execution={"mission_id":mid,"status":_mission2110(mid).get("status")}
    else:
        context=[]
        with _DB_LOCK_2110,_db2110() as c:
            rows=c.execute("SELECT role,content FROM infinity_messages_2110 WHERE conversation_id=? ORDER BY id DESC LIMIT 12",(cid,)).fetchall()
        for r in reversed(rows):context.append({"role":r["role"],"content":r["content"]})
        answer,provider,errors=_model_call2110(context,system="You are AI Infinity. Do not fabricate actions, credentials, sources, or results.")
        reply=answer or _builtin_chat2110(req.message); execution=None; execution={"mode":"conversation","provider":provider,"errors":errors}
    _message2110(cid,user,"assistant",reply,execution or {})
    return {"conversation_id":cid,"message":{"role":"assistant","content":reply},"execution":execution,"version":INFINITY_VERSION_2110}


@app.get("/chat/{conversation_id}")
def _chat_history2110(conversation_id:str,user_id:str="default"):
    user=_ensure_user2110(user_id)
    with _DB_LOCK_2110,_db2110() as c:
        rows=c.execute("SELECT role,content,metadata_json,created_at FROM infinity_messages_2110 WHERE conversation_id=? AND user_id=? ORDER BY id",(conversation_id,user)).fetchall()
    return {"conversation_id":conversation_id,"user_id":user,"messages":[{"role":r["role"],"content":r["content"],"metadata":_json_2110.loads(r["metadata_json"] or "{}"),"created_at":r["created_at"]} for r in rows]}


@app.post("/infinity/command")
def _command2110(req:_Command2110):
    user=_ensure_user2110(req.user_id); plan=_plan2110(req.command,user)
    if req.simulate:
        return {"status":"simulated","version":INFINITY_VERSION_2110,"build":INFINITY_BUILD_2110,"plan":plan,"truthful":True}
    if plan["approval_required"] and not req.approved:
        return {"status":"awaiting_approval","plan":plan,"next_action":"grant scoped authority and resubmit with approval","truthful":True}
    mid=_create_mission2110(user,req.command,plan,plan["approval_required"])
    _run_mission2110(mid,user,req.command,plan,req.approved)
    return {"status":_mission2110(mid)["status"],"mission_id":mid,"mission":_mission2110(mid),"truthful":True}

# ---------- production factory ----------
_FACTORY_STAGES_2110=[
    "understand","discover","decompose","plan","dependency_check","authority_check",
    "authorize","execute","verify","reconcile","learn","close","report"
]


def _factory2110(objective,user_id):
    plan=_plan2110(objective,user_id)
    discovery=_discover2110(objective,8) if plan["intent"] in {"research","planning","read_action"} else {"sources":[],"source_count":0,"independent_domains":0,"errors":[]}
    return {"factory":"AI Infinity Production Factory","version":INFINITY_VERSION_2110,"objective":objective,"stages":[{"name":x,"status":"ready" if x not in {"authorize","execute"} else ("approval_required" if plan["approval_required"] else "ready")} for x in _FACTORY_STAGES_2110],"intent":plan["intent"],"plan":plan,"discovery":discovery,"execution_contract":{"no_arbitrary_code":True,"no_uncertain_replay":True,"side_effects_require_scoped_authority":True,"result_verification":True}}


