    mid=_create_mission2110(user,req.objective,f["plan"],f["plan"]["approval_required"])
    _run_mission2110(mid,user,req.objective,f["plan"],req.approved)
    return {"status":_mission2110(mid)["status"],"mission_id":mid,"factory":f,"mission":_mission2110(mid)}

