# ---------- 100-step consolidation + further dependency graph ----------
_ROADMAP_2110=[]
for i in range(1,101):
    # The public registry is deliberately explicit: each stage has a native
    # foundation and declares its likely dependency class.
    deps=[]
    if i>=11: deps.append("model-or-builtin-reasoning")
    if i>=21: deps.append("provider-router")
    if i>=31: deps.append("persistent-memory")
    if i>=41: deps.append("evidence-research")
    if i>=51: deps.append("action-fabric")
    if i>=71: deps.append("scoped-authority")
    if i>=81: deps.append("durable-recovery")
    if i>=91: deps.append("professional-interface")
    _ROADMAP_2110.append({"step":i,"name":f"Peak capability stage {i}","foundation":True,"dependency_classes":deps})

# Replace generic labels with the actual roadmap's 10 phase anchors.
_PHASES_2110={
1:"production foundation",11:"AI brain",21:"free-first intelligence",31:"memory",41:"world knowledge",51:"real-world action",61:"human-level digital workflows",71:"authority",81:"self-recovery/adaptation",91:"platform/mission OS"
}
for x in _ROADMAP_2110:
    x["phase"]=_PHASES_2110[max(k for k in _PHASES_2110 if k<=x["step"])]

@app.get("/infinity/roadmap")
def _roadmap2110():
    return {"version":INFINITY_VERSION_2110,"stages":_ROADMAP_2110,"consolidated_in_this_layer":True,"note":"A capability is only reported READY when its runtime dependency is actually configured."}

