def _2275_connection_states(user_id="default"):
    user = (user_id or "default").strip()[:200] or "default"
    states = {}
    try:
        with _DB_LOCK_2110, _db2110() as c:
            rows = c.execute("SELECT kind,name,status,capabilities_json FROM infinity_connections_2110 WHERE user_id=?",(user,)).fetchall()
        for r in rows:
            states[str(r["kind"])] = {"name":r["name"],"status":r["status"],"capabilities":_json_2110.loads(r["capabilities_json"] or "[]")}
    except Exception:
        pass
    return states


def _2275_platform_status(user_id="default"):
    conns = _2275_connection_states(user_id)
    out=[]
    for p in PLATFORM_CATALOG_2275:
        if p["connector_kind"] in ("internal","public_http"):
            ready = p["status"] == "ready"
            status = "READY" if ready else "WAITING"
        else:
            c = conns.get(p["connector_kind"])
            ready = bool(c and str(c.get("status","" )).lower() in {"connected","active","ready"})
            status = "READY" if ready else "CONNECT"
        out.append({**p,"ready":ready,"runtime_status":status})
    return out


def _2275_classify_command(command):
    q=(command or "").strip()
    low=q.lower()
    tags=[]
    if any(x in low for x in ("research","investigate","find out","evidence","compare","analyze")): tags.append("research")
    if any(x in low for x in ("sell","revenue","income","customer","client","business","earn","monetize","offer")): tags.append("revenue")
    if any(x in low for x in ("video","podcast","thumbnail","script","media","youtube","film","audio")): tags.append("media")
    if any(x in low for x in ("github","slack","gmail","google","microsoft","browser","website","platform","publish","post")): tags.append("platform")
    if any(x in low for x in ("remember","memory","save this","learn")): tags.append("memory")
    if any(x in low for x in ("schedule","recurring","every day","every week")): tags.append("automation")
    if not tags: tags=["general-mission"]
    departments=[]
    if "research" in tags: departments.append("Research Intelligence")
    if "revenue" in tags: departments.extend(["Products and Services","Growth and Distribution","Finance and Economics"])
    if "media" in tags: departments.append("Infinity Media Studio")
    if "platform" in tags: departments.append("Platform Operations")
    if not departments: departments.append("Operations")
    return {"command":q,"intent_tags":tags,"departments":list(dict.fromkeys(departments)),"safety_mode":"bounded-and-verifiable","free_first":True}


