@app.post("/infinity/2275/command")
def _f2275_command(payload: Dict[str,Any]):
    command=str(payload.get("command") or payload.get("objective") or "").strip()[:8000]
    if not command: raise HTTPException(400,"command is required")
    c=_2275_classify_command(command)
    plan=[]
    if "research" in c["intent_tags"]: plan.append({"stage":"research","action":"collect diverse public evidence and verify claims"})
    if "revenue" in c["intent_tags"]: plan.append({"stage":"economics","action":"map zero-cost offer, customer, distribution, proof and revenue path"})
    if "media" in c["intent_tags"]: plan.append({"stage":"media","action":"build script, production plan, asset checklist and distribution package"})
    if "platform" in c["intent_tags"]: plan.append({"stage":"platforms","action":"build parallel platform tasks and require live connector readiness before external execution"})
    plan.extend([{
        "stage":"verification","action":"define observable success criteria and evidence"
    },{"stage":"recovery","action":"define bounded fallback and human escalation"},{"stage":"closure","action":"save outcome, provenance and reusable learning"}])
    return {"status":"planned","version":FINAL2275_VERSION,"classification":c,"plan":plan,"free_first":True,"external_execution": "requires_live_capability_and_scoped_authority","truthful":True}


