@app.post("/infinity/2275/platforms/batch-plan")
def _f2275_platform_batch(payload: Dict[str,Any]):
    command=str(payload.get("command") or payload.get("objective") or "").strip()[:4000]
    requested=list(dict.fromkeys(str(x)[:80] for x in (payload.get("platforms") or [])))
    if not command or not requested: raise HTTPException(400,"command and platforms are required")
    known={p["platform_id"]:p for p in PLATFORM_CATALOG_2275}
    unknown=[x for x in requested if x not in known]
    if unknown: raise HTTPException(400,"unknown platform: " + ", ".join(unknown[:10]))
    group=_2275_uid("parallel")
    states={x["platform_id"]:x for x in _2275_platform_status(str(payload.get("user_id") or "default"))}
    rows=[]
    with _DB_LOCK_2110, _db2110() as c:
        for pid in requested:
            p=known[pid]; state=states[pid]
            status="planned" if state["ready"] else "awaiting_connection"
            task=_2275_uid("platform-task")
            t=_2275_now()
            c.execute("INSERT INTO ai2275_platform_tasks(task_id,org_id,platform_id,parallel_group,command,mode,status,result_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(task,AI_INFINITY_2275_ORG_ID,pid,group,command,"simulate" if str(payload.get("mode","plan"))!="execute" else "execute",status,None,t,t))
            rows.append({"task_id":task,"platform_id":pid,"platform":p["name"],"status":status,"ready":state["ready"],"capabilities":p["capabilities"],"external_execution_proof_required":pid not in {"media-studio","web-public"}})
    _2275_log(AI_INFINITY_2275_ORG_ID,"owner","platform.batch_planned",command,{"parallel_group":group,"platforms":requested})
    return {"status":"planned","parallel_group":group,"command":command,"tasks":rows,"simultaneous":True,"note":"Parallel means independently queued and tracked; it does not mean unconfigured external accounts are silently accessed.","truthful":True}


