@app.post("/infinity/2275/platforms/task/{task_id}/complete")
def _f2275_platform_complete(task_id: str, payload: Dict[str,Any]):
    # Completion is receipt-driven. A client cannot claim an external platform
    # side effect as verified unless it supplies an explicit proof reference.
    proof=str(payload.get("proof_ref") or "").strip()[:1000]
    result=payload.get("result") or {}
    status="completed" if proof else "completed_without_external_proof"
    with _DB_LOCK_2110, _db2110() as c:
        row=c.execute("SELECT task_id FROM ai2275_platform_tasks WHERE task_id=? AND org_id=?",(task_id,AI_INFINITY_2275_ORG_ID)).fetchone()
        if not row: raise HTTPException(404,"task not found")
        c.execute("UPDATE ai2275_platform_tasks SET status=?,result_json=?,updated_at=? WHERE task_id=?",(status,_json_2110.dumps({"result":result,"proof_ref":proof}),_2275_now(),task_id))
    return {"status":status,"task_id":task_id,"proof_ref":proof or None,"verified_external_effect":bool(proof),"truthful":True}


