@app.post("/infinity/2275/revenue/opportunities")
def _f2275_revenue_opportunities(payload: Dict[str,Any]):
    problem=str(payload.get("problem") or payload.get("customer_problem") or payload.get("command") or "").strip()[:1800]
    if not problem: raise HTTPException(400,"problem or command is required")
    low=problem.lower()
    preferred=[]
    if any(k in low for k in ("video","content","media","youtube")): preferred.append("media")
    if any(k in low for k in ("research","analysis","report","data")): preferred.append("research")
    if any(k in low for k in ("software","app","automation","website")): preferred.extend(["software","automation"])
    if any(k in low for k in ("course","training","education")): preferred.append("education")
    if not preferred: preferred=["service","digital-product","automation"]
    preferred=list(dict.fromkeys(preferred))[:4]
    created=[]
    t=_2275_now()
    with _DB_LOCK_2110, _db2110() as c:
        for lane in preferred:
            meta=next(x for x in REVENUE_LANES_2275 if x["lane"]==lane)
            oid=_2275_uid("opportunity")
            title=meta["name"] + " for: " + problem[:90]
            offer=meta["free_start"]
            distribution="Use free/public channels, direct outreach only where permitted, partnerships, search discovery and reusable proof assets."
            c.execute("INSERT INTO ai2275_opportunities(opportunity_id,org_id,lane,title,customer_problem,offer,distribution,state,evidence_ref,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(oid,AI_INFINITY_2275_ORG_ID,lane,title,problem,offer,distribution,"candidate",None,t,t))
            created.append({"opportunity_id":oid,"lane":lane,"title":title,"state":"candidate","offer":offer,"distribution":distribution,"value":"unpriced until market evidence is collected"})
    _2275_log(AI_INFINITY_2275_ORG_ID,"owner","revenue.opportunities_created",problem,{"count":len(created)})
    return {"status":"created","opportunities":created,"count":len(created),"zero_cost_start":True,"no_guaranteed_revenue":True,"truthful":True}


