@app.post("/infinity/2275/media/projects/{media_id}/package")
def _f2275_media_package(media_id: str, payload: Dict[str,Any]):
    with _DB_LOCK_2110, _db2110() as c:
        row=c.execute("SELECT * FROM ai2275_media_projects WHERE media_id=? AND org_id=?",(media_id,AI_INFINITY_2275_ORG_ID)).fetchone()
        if not row: raise HTTPException(404,"media project not found")
        title=row["title"]; objective=row["objective"]; audience=row["audience"]; fmt=row["format"]
    hook=str(payload.get("hook") or objective).strip()[:500]
    key_points=[x.strip() for x in str(payload.get("key_points") or objective).split(";") if x.strip()][:12]
    script=(f"TITLE: {title}\n\nHOOK: {hook}\n\nAUDIENCE: {audience}\n\n"
            "NARRATION / DIALOGUE:\n" + "\n".join(f"{i+1}. {p}" for i,p in enumerate(key_points)) +
            "\n\nCALL TO ACTION:\nInvite the audience to take the documented next step.")
    shotlist=[]
    for i,p in enumerate(key_points or [objective]):
        shotlist.append({"scene":i+1,"visual":p,"audio":"Narration or dialogue aligned to the scene.","asset_source":"original, user-owned, public-domain or license-verified asset only"})
    captions=[]; cursor=0
    for i,p in enumerate(key_points[:20] or [objective]):
        start=cursor; end=cursor+6; cursor=end
        def ts(sec):
            h=sec//3600; m=(sec%3600)//60; s=sec%60
            return f"{h:02d}:{m:02d}:{s:02d},000"
        captions.append(f"{i+1}\n{ts(start)} --> {ts(end)}\n{p}\n")
    srt="\n".join(captions)
    slug=re.sub(r"[^a-z0-9]+","-",title.lower()).strip("-") or "media-project"
    studio_dir=_WORK_2110 / "media" / media_id
    studio_dir.mkdir(parents=True,exist_ok=True)
    (studio_dir/"script.txt").write_text(script,encoding="utf-8")
    (studio_dir/"shotlist.json").write_text(_json_2110.dumps(shotlist,ensure_ascii=False,indent=2),encoding="utf-8")
    (studio_dir/"captions.srt").write_text(srt,encoding="utf-8")
    svg=f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900"><rect width="1600" height="900" fill="#07101d"/><circle cx="1350" cy="150" r="210" fill="#18365c"/><text x="100" y="330" fill="#f6f9ff" font-size="82" font-family="system-ui, sans-serif" font-weight="800">{_escape_2275(title)}</text><text x="100" y="430" fill="#9fb1c8" font-size="34" font-family="system-ui, sans-serif">AI Infinity Media Studio · Free-first production pack</text><text x="100" y="760" fill="#6e8db1" font-size="28" font-family="system-ui, sans-serif">{_escape_2275(fmt)} · { _escape_2275(audience[:80]) }</text></svg>"""
    (studio_dir/f"{slug}.svg").write_text(svg,encoding="utf-8")
    package={"script":"script.txt","shotlist":"shotlist.json","captions":"captions.srt","poster_svg":f"{slug}.svg","format":fmt,"free_first":True,"asset_policy":"license-verified or user-owned assets"}
    with _DB_LOCK_2110, _db2110() as c:
        c.execute("UPDATE ai2275_media_projects SET status=?,script=?,shotlist_json=?,package_json=?,updated_at=? WHERE media_id=?",("package_ready",script,_json_2110.dumps(shotlist,ensure_ascii=False),_json_2110.dumps(package,ensure_ascii=False),_2275_now(),media_id))
    return {"status":"package_ready","media_id":media_id,"package":package,"workspace_path":str(studio_dir),"capabilities":["script","shotlist","subtitles","svg-poster"],"external_video_rendering":False,"truthful":True}


