@app.post("/infinity/2275/delegation")
def _f2275_delegation(payload: Dict[str,Any]):
    user_id=str(payload.get("user_id") or "default").strip()[:200] or "default"
    scopes=sorted(set(str(x)[:120] for x in (payload.get("scopes") or ["conversation","research","mission","memory"])))[:100]
    platform_scope=sorted(set(str(x)[:120] for x in (payload.get("platforms") or ["web-public","media-studio"])))[:100]
    budget=payload.get("budget_limit")
    budget_value=float(budget) if budget is not None else None
    expires_seconds=max(60,min(int(payload.get("expires_seconds") or 86400),31_536_000))
    did=_2275_uid("delegation")
    exp=_2275_now()+expires_seconds
    with _DB_LOCK_2110, _db2110() as c:
        c.execute("INSERT INTO ai2275_delegations(delegation_id,org_id,user_id,scopes_json,platform_scope_json,budget_limit,status,created_at,expires_at,revoked_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(did,AI_INFINITY_2275_ORG_ID,user_id,_json_2110.dumps(scopes),_json_2110.dumps(platform_scope),budget_value,"active",_2275_now(),exp,None))
    _2275_log(AI_INFINITY_2275_ORG_ID,user_id,"delegation.granted","Scoped delegation created",{"delegation_id":did,"scopes":scopes,"platforms":platform_scope})
    return {"status":"active","delegation_id":did,"user_id":user_id,"scopes":scopes,"platforms":platform_scope,"budget_limit":budget_value,"expires_at":exp,"revocable":True,"external_identity_proof":False,"truthful":True}


