    with _DB_LOCK_2110, _db2110() as c:
        revenue=c.execute("SELECT COALESCE(SUM(amount),0) FROM ai2275_revenue_ledger WHERE org_id=? AND verification_status='verified_receipt'",(AI_INFINITY_2275_ORG_ID,)).fetchone()[0]
        open_opp=c.execute("SELECT COUNT(*) FROM ai2275_opportunities WHERE org_id=? AND state NOT IN ('closed','rejected')",(AI_INFINITY_2275_ORG_ID,)).fetchone()[0]
        media_ready=c.execute("SELECT COUNT(*) FROM ai2275_media_projects WHERE org_id=? AND status='package_ready'",(AI_INFINITY_2275_ORG_ID,)).fetchone()[0]
