def _2300_offer_factory(problem: str, limit: int = 6):
    q=str(problem or "").strip()[:1800]
    if not q: raise ValueError("problem_required")
    low=q.lower()
    ranked=[]
    for item in OFFER_FRAMEWORKS_2300:
        score=0
        terms={"service":("service","operations","work"),"research":("research","analysis","evidence","report"),"software":("software","app","website","product"),"digital-product":("template","guide","playbook","kit"),"media":("video","content","media","youtube","podcast"),"education":("course","training","learn","education"),"publishing":("book","publication","manuscript","writing"),"partnership":("partner","sponsor","community"),"marketplace":("marketplace","freelance","gig"),"automation":("automation","workflow","repetitive","process"),"data":("dataset","data","monitoring"),"capital":("grant","funding","sponsor","non-dilutive")}
        score=sum(1 for t in terms.get(item["lane"],()) if t in low)
        ranked.append((score,item))
    ranked.sort(key=lambda x:(x[0],x[1]["lane"]),reverse=True)
    return [x[1] for x in ranked[:max(1,min(limit,12))]]


def _2300_expand_organization(reason: str, requested_roles: Optional[List[str]]=None):
    q=str(reason or "organizational capability expansion").strip()[:1200]
    low=q.lower()
    desired=[]
    if requested_roles: desired.extend(str(x).strip() for x in requested_roles)
    for needle, roles in [
        (("research","evidence","analysis"),["research-lead","evidence-analyst","market-analyst"]),
        (("code","software","engineering","integration"),["principal-engineer","integration-engineer","reliability-engineer"]),
        (("revenue","sell","sales","customer","income"),["market-analyst","growth-strategist","sales-operator","pricing-analyst","customer-success"]),
        (("media","video","content","youtube","film"),["media-director","script-producer","visual-producer","distribution-editor"]),
        (("security","privacy","risk"),["security-engineer","compliance-coordinator"]),
        (("platform","github","gmail","browser","device"),["platform-orchestrator","account-manager","device-coordinator"]),
        (("finance","budget","reinvestment"),["finance-controller","reinvestment-planner","pricing-analyst"]),
    ]:
        if any(x in low for x in needle): desired.extend(roles)
    if not desired: desired=["chief-of-staff","operations-manager","learning-manager"]
    desired=list(dict.fromkeys(desired))
    created=[]
    with _DB_LOCK_2110, _db2110() as c:
        for role_id in desired[:12]:
            row=c.execute("SELECT role_id FROM ai2300_role_registry WHERE role_id=? AND org_id=?",(role_id,AI_INFINITY_2275_ORG_ID)).fetchone()
            if row:
                c.execute("UPDATE ai2300_role_registry SET capacity=capacity+1,updated_at=? WHERE role_id=?",(_2275_now(),role_id))
                created.append({"role_id":role_id,"action":"capacity_increased"})
            else:
                custom=_2275_uid("role")
                department="Expansion Lab"
                specialization="custom capability requested: " + role_id.replace("-"," ")
                c.execute("INSERT INTO ai2300_role_registry(role_id,org_id,department,name,specialization,status,capacity,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",(custom,AI_INFINITY_2275_ORG_ID,department,role_id.replace("-"," ").title(),specialization,"active",1,_2275_now(),_2275_now()))
                created.append({"role_id":custom,"requested_role":role_id,"action":"custom_role_created","department":department})
    _2275_log(AI_INFINITY_2275_ORG_ID,"2300-organization","organization.expanded",q,{"created":created})
    return {"reason":q,"roles":created,"expansion_is_policy_only":True,"arbitrary_code_execution":False}


