def _f2300_free_check(payload: Dict[str,Any]):
    url=str(payload.get("url") or "").strip()
    if not url or not _safe_public_url2110(url): raise HTTPException(400,"safe public http(s) url required")
    try:
        f=_fetch_evidence2110(url)
        return {"status":"checked","url":url,"http_status":f["status"],"content_type":f["content_type"],"content_hash":f["hash"],"available":True,"terms_still_need_human_or_policy_review":True,"truthful":True}
    except Exception as exc:
        return {"status":"checked","url":url,"available":False,"error":str(exc)[:400],"truthful":True}


def _2300_parallel_one(task):
    task_id=task["task_id"]; target=task["target"]; kind=task["kind"]; instruction=task["instruction"]
    started=_2275_now()
    try:
        if kind=="public_get":
            if not _safe_public_url2110(target): raise ValueError("destination_not_public_or_safe")
            f=_fetch_evidence2110(target)
            result={"target":target,"http_status":f["status"],"content_type":f["content_type"],"excerpt":f["text"][:1600],"content_hash":f["hash"],"instruction":instruction,"external_side_effects":False}
            status="completed_verified"
        elif kind=="internal":
            result={"target":target,"instruction":instruction,"execution":"internal-plan-ready","external_side_effects":False}
            status="completed"
        elif kind=="media":
            result={"target":target,"instruction":instruction,"execution":"media-production-plan-ready","external_side_effects":False}
            status="completed"
        else:
            result={"target":target,"instruction":instruction,"execution":"awaiting_configured_connector","external_side_effects":False}
            status="awaiting_connection"
        return {"task_id":task_id,"status":status,"result":result,"latency_ms":int((_2275_now()-started)*1000)}
    except Exception as exc:
        return {"task_id":task_id,"status":"failed_closed","result":{"error":str(exc)[:400],"instruction":instruction},"latency_ms":int((_2275_now()-started)*1000)}


@app.post("/infinity/2300/parallel/plan")
def _f2300_parallel_plan(payload: Dict[str,Any]):
    objective=str(payload.get("objective") or payload.get("command") or "").strip()[:4000]
    raw_tasks=payload.get("tasks") or []
    if not objective or not isinstance(raw_tasks,list) or not raw_tasks: raise HTTPException(400,"objective and tasks are required")
    run_id=_2275_uid("parallel-run")
    t=_2275_now()
    with _DB_LOCK_2110,_db2110() as c:
        c.execute("INSERT INTO ai2300_parallel_runs(run_id,org_id,objective,status,summary_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?)",(run_id,AI_INFINITY_2275_ORG_ID,objective,"planned",None,t,t))
        for item in raw_tasks[:20]:
            target=str(item.get("target") or item.get("platform") or "").strip()[:1000]
            kind=str(item.get("kind") or "internal").strip()[:50]
            instruction=str(item.get("instruction") or objective).strip()[:1500]
            if not target: continue
            tid=_2275_uid("parallel-task")
            c.execute("INSERT INTO ai2300_parallel_tasks(task_id,run_id,target,kind,instruction,status,result_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",(tid,run_id,target,kind,instruction,"planned",None,t,t))
    return {"status":"planned","run_id":run_id,"task_count":len(raw_tasks[:20]),"parallelism":"independent bounded tasks","note":"Only safe internal/public-read tasks may execute without external authority.","truthful":True}


@app.post("/infinity/2300/parallel/execute/{run_id}")
def _f2300_parallel_execute(run_id: str):
    with _DB_LOCK_2110,_db2110() as c:
        rows=[dict(r) for r in c.execute("SELECT * FROM ai2300_parallel_tasks WHERE run_id=? ORDER BY created_at",(run_id,)).fetchall()]
        if not rows: raise HTTPException(404,"parallel run not found")
        c.execute("UPDATE ai2300_parallel_runs SET status='running',updated_at=? WHERE run_id=?",(_2275_now(),run_id))
    results=[]
    with _cf_2300.ThreadPoolExecutor(max_workers=min(8,max(1,len(rows)))) as ex:
        futures=[ex.submit(_2300_parallel_one,r) for r in rows]
        for fut in _cf_2300.as_completed(futures): results.append(fut.result())
    results.sort(key=lambda x:x["task_id"])
    with _DB_LOCK_2110,_db2110() as c:
        for r in results:
            c.execute("UPDATE ai2300_parallel_tasks SET status=?,result_json=?,updated_at=? WHERE task_id=?",(r["status"],_json_2110.dumps(r["result"],ensure_ascii=False),_2275_now(),r["task_id"]))
        final_status="completed" if all(r["status"] in {"completed","completed_verified","awaiting_connection"} for r in results) else "completed_with_failures"
        summary={"task_count":len(results),"completed":sum(r["status"].startswith("completed") for r in results),"awaiting_connection":sum(r["status"]=="awaiting_connection" for r in results),"failed":sum(r["status"]=="failed_closed" for r in results)}
        c.execute("UPDATE ai2300_parallel_runs SET status=?,summary_json=?,updated_at=? WHERE run_id=?",(final_status,_json_2110.dumps(summary),_2275_now(),run_id))
    return {"status":final_status,"run_id":run_id,"summary":summary,"results":results,"arbitrary_code_execution":False,"uncertain_external_replay":False,"truthful":True}


@app.get("/infinity/2300/parallel/{run_id}")
def _f2300_parallel_get(run_id: str):
    with _DB_LOCK_2110,_db2110() as c:
        run=c.execute("SELECT * FROM ai2300_parallel_runs WHERE run_id=? AND org_id=?",(run_id,AI_INFINITY_2275_ORG_ID)).fetchone()
        if not run: raise HTTPException(404,"parallel run not found")
        tasks=[dict(r) for r in c.execute("SELECT * FROM ai2300_parallel_tasks WHERE run_id=? ORDER BY created_at",(run_id,)).fetchall()]
    return {"run":dict(run),"tasks":tasks,"truthful":True}


@app.post("/infinity/2300/media/production-plan")
def _f2300_media_production_plan(payload: Dict[str,Any]):
    title=str(payload.get("title") or "Infinity Media Production").strip()[:200]
    objective=str(payload.get("objective") or "").strip()[:1600]
    audience=str(payload.get("audience") or "general audience").strip()[:300]
    if not objective: raise HTTPException(400,"objective is required")
    created=_f2275_media_project({"title":title,"format":str(payload.get("format") or "video"),"audience":audience,"objective":objective})
    package=_f2275_media_package(created["media_id"],{})
    media_id=created["media_id"]
    studio_dir=_WORK_2110/"media"/media_id
    variants={
        "short_form": ["hook_30s.txt","value_60s.txt","cta_20s.txt"],
        "long_form": ["intro.txt","main_story.txt","proof.txt","conclusion.txt"],
        "distribution": ["title_variants.txt","description_variants.txt","caption_variants.txt"],
    }
    for group,names in variants.items():
        for name in names:
            content=f"AI Infinity Media Studio\nGROUP: {group}\nPROJECT: {title}\nOBJECTIVE: {objective}\nAUDIENCE: {audience}\n\nThis is a production planning artifact. Validate claims, rights, sources and platform requirements before publication.\n"
            (studio_dir/name).write_text(content,encoding="utf-8")
            aid=_2275_uid("media-asset")
            with _DB_LOCK_2110,_db2110() as c:
                c.execute("INSERT INTO ai2300_media_assets(asset_id,media_id,asset_type,path,provenance,status,created_at) VALUES(?,?,?,?,?,?,?)",(aid,media_id,group,str((studio_dir/name).relative_to(_WORK_2110)),"originally generated by AI Infinity; verify all external inputs","ready",_2275_now()))
    return {"status":"production_plan_ready","media_id":media_id,"base_package":package,"asset_groups":variants,"free_first":True,"external_rendering":False,"truthful":True}


