def _2600_now() -> float:
    return time.time()


def _2600_uid(prefix: str) -> str:
    return f"{prefix}-2600-{uuid.uuid4().hex[:12]}"


def _2600_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str, separators=(",", ":"))


def _2600_digest(value: Any) -> str:
    return hashlib.sha256(_2600_json(value).encode("utf-8")).hexdigest()


def _2600_slug(text_value: str, max_len: int = 90) -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "-", str(text_value or "").strip().lower()).strip("-")
    return (s or "artifact")[:max_len]


def _2600_log(mission_id: Optional[str], event: str, detail: Any) -> None:
    with _DB_LOCK_2110, _db2110() as c:
        c.execute(
            "INSERT INTO ai2600_runs(run_id,mission_id,event,detail_json,created_at) VALUES(?,?,?,?,?)",
            (_2600_uid("run"), mission_id, str(event)[:120], _2600_json(detail)[:30000], _2600_now()),
        )


def _2600_write_artifact(mission_id: str, kind: str, title: str, content: str) -> Dict[str, Any]:
    root = WORKSPACE / "infinity-2600" / mission_id
    root.mkdir(parents=True, exist_ok=True)
    safe_name = _2600_slug(title) + ".md"
    path = root / safe_name
    data = content if content.endswith("\n") else content + "\n"
    path.write_text(data, encoding="utf-8")
    h = hashlib.sha256(data.encode("utf-8")).hexdigest()
    aid = _2600_uid("artifact")
    with _DB_LOCK_2110, _db2110() as c:
        c.execute(
            "INSERT INTO ai2600_artifacts(artifact_id,mission_id,kind,title,path,content_hash,status,provenance_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)",
            (aid, mission_id, kind[:100], title[:240], str(path), h, "ready", _2600_json({"source":"AI Infinity 2600","mission_id":mission_id}), _2600_now()),
        )
    return {"artifact_id":aid,"kind":kind,"title":title,"path":str(path),"sha256":h,"status":"ready"}


def _2600_split_objective(objective: str) -> List[str]:
    text_value = re.sub(r"\s+", " ", str(objective or "").strip())
    if not text_value:
        return []
    parts = re.split(r"\s*(?:;|\n+|\bthen\b|\band then\b)\s*", text_value, flags=re.I)
    parts = [x.strip(" .") for x in parts if x.strip(" .")]
    if len(parts) == 1 and len(parts[0]) > 4000:
        parts = [parts[0][:4000]]
    return parts[:12]


def _2600_classify_instruction(instruction: str) -> List[str]:
    q = str(instruction or "").lower()
    kinds: List[str] = []
    if any(x in q for x in ("research", "investigate", "find evidence", "compare", "sources", "analyze")):
        kinds.append("research")
    if any(x in q for x in ("remember", "memorize", "save this", "store this")):
        kinds.append("memory")
    if any(x in q for x in ("revenue", "make money", "sell", "customer", "customers", "offer", "business", "income", "monetize", "market")):
        kinds.extend(["opportunity_discovery", "customer_discovery", "offer_factory", "distribution"])
    if any(x in q for x in ("media", "video", "youtube", "content", "podcast", "thumbnail", "script")):
        kinds.append("media")
    if any(x in q for x in ("free", "zero cost", "$0", "open source", "free resource")):
        kinds.append("free_resource")
    if any(x in q for x in ("email", "gmail", "slack", "github", "microsoft", "browser", "website", "navigate", "click", "device", "phone", "send", "post")):
        kinds.append("external_action")
    if any(x in q for x in ("report", "document", "file", "proposal", "brief", "plan", "package", "write")):
        kinds.append("artifact")
    if any(x in q for x in ("learn", "improve", "self improve", "optimize", "feedback", "lesson")):
        kinds.append("learning")
    if not kinds:
        kinds.append("general")
    # Stable order keeps self-test and UI deterministic.
    order = ["research","customer_discovery","opportunity_discovery","offer_factory","distribution","media","free_resource","external_action","memory","artifact","learning","general"]
    return sorted(set(kinds), key=lambda x: order.index(x) if x in order else 99)


def _2600_public_research(objective: str, mission_id: str, limit: int = 8) -> Dict[str, Any]:
    discovered = _discover2110(objective, max(4, min(int(limit), 8)))
    sources = list(discovered.get("sources") or [])[:8]
    evidence: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []

    def fetch_one(src: Dict[str, Any]) -> Dict[str, Any]:
        url = str(src.get("url") or "")
        try:
            f = _fetch_evidence2110(url)
            return {"ok":True,"source":src,"fetch":f}
        except Exception as exc:
            return {"ok":False,"source":src,"error":str(exc)[:300]}

    with _cf_2300.ThreadPoolExecutor(max_workers=min(6, max(1, len(sources)))) as ex:
        futures = [ex.submit(fetch_one, s) for s in sources]
        for fut in _cf_2300.as_completed(futures):
            result = fut.result()
            if result["ok"]:
                src = result["source"]; f = result["fetch"]
                item = {
                    "url":src.get("url"),
                    "domain":src.get("domain"),
                    "title":src.get("title") or src.get("url"),
                    "source_family":src.get("source_family"),
                    "relevance":src.get("relevance"),
                    "excerpt":str(f.get("text") or "")[:1800],
                    "content_hash":f.get("hash"),
                    "http_status":f.get("status"),
                }
                evidence.append(item)
                try:
                    eid = _uid2110("evidence")
                    with _DB_LOCK_2110, _db2110() as c:
                        c.execute(
                            "INSERT INTO infinity_evidence_2110(evidence_id,mission_id,user_id,url,domain,title,excerpt,source_family,retrieved_at,content_hash,relevance) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                            (eid, mission_id, "default", item["url"], item["domain"], item["title"], item["excerpt"], item.get("source_family"), _now2110(), item.get("content_hash"), float(item.get("relevance") or 0.5)),
                        )
                except Exception:
                    pass
            else:
                errors.append({"url":result["source"].get("url"),"error":result.get("error")})
    evidence.sort(key=lambda x: (str(x.get("domain")), str(x.get("url"))))
    domains = sorted({str(x.get("domain")) for x in evidence if x.get("domain")})
    verified = len(evidence) >= 2 and len(domains) >= 2
    return {
        "status":"completed",
        "query":objective,
        "discovery":discovered,
        "evidence":evidence,
        "errors":errors,
        "evidence_count":len(evidence),
        "independent_domains":len(domains),
        "verified":verified,
        "verification_basis":"at least two fetched evidence items from two domains" if verified else "insufficient independent fetched evidence for verification",
    }


def _2600_customer_discovery(objective: str, mission_id: str) -> Dict[str, Any]:
    research = _2600_public_research(objective, mission_id, limit=6)
    created = []
    for src in research.get("evidence", [])[:8]:
        url = str(src.get("url") or "")
        domain = str(src.get("domain") or (urlparse(url).netloc if url else ""))[:200]
        title = str(src.get("title") or "source")[:500]
        excerpt = str(src.get("excerpt") or "")[:700]
        signal = excerpt.replace("\n", " ").strip()[:600]
        fit = min(1.0, 0.45 + (0.1 if objective.lower().split() and objective.lower().split()[0] in title.lower() else 0.0) + (0.1 if len(excerpt) > 250 else 0.0))
        lid = _2600_uid("lead")
        with _DB_LOCK_2110, _db2110() as c:
            c.execute(
                "INSERT INTO ai2600_leads(lead_id,mission_id,source_url,source_domain,title,problem_signal,fit_score,status,provenance_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
                (lid, mission_id, url, domain, title, signal, fit, "research_candidate", _2600_json({"mission_id":mission_id,"evidence_hash":src.get("content_hash")}), _2600_now()),
            )
        created.append({"lead_id":lid,"domain":domain,"title":title,"fit_score":fit,"status":"research_candidate","contacted":False,"customer_verified":False,"source_url":url})
    return {"status":"completed","candidates":created,"count":len(created),"contacted":False,"customers_fabricated":False,"research_verified":research.get("verified",False)}


def _2600_offer_factory(problem: str, mission_id: str) -> Dict[str, Any]:
    base = _2300_offer_factory(problem, limit=8)
    offers = (base.get("offers") or []) if isinstance(base, dict) else list(base or [])
    artifacts = []
    for item in offers[:6]:
        title = str(item.get("offer") or "AI Infinity Offer")
        content = "# " + title + "\n\n"
        content += "Customer problem\n\n" + str(item.get("customer") or problem) + "\n\n"
        content += "Proof plan\n\n" + str(item.get("proof") or "Define observable outcomes and evidence before delivery.") + "\n\n"
        content += "Operating rule\n\nFree-first, truthful, scope-controlled, no guaranteed revenue.\n"
        artifacts.append(_2600_write_artifact(mission_id, "offer", title, content))
    return {"status":"completed","offers":offers[:8],"offer_artifacts":artifacts,"guaranteed_revenue":False,"counts_as_revenue":False}


