def _2600_quality(result: Dict[str, Any]) -> Dict[str, Any]:
    checks=[]
    def ck(name: str, passed: bool, detail: Any=None):
        x={"name":name,"passed":bool(passed)}
        if detail is not None:x["detail"]=detail
        checks.append(x)
    ck("result is object", isinstance(result, dict))
    ck("status recorded", bool(result.get("status")))
    ck("truth boundary present", result.get("truthful") is True or "truthful" not in result)
    ck("no automatic uncertain replay", result.get("automatic_uncertain_replay", False) is False)
    return {"passed":all(x["passed"] for x in checks),"checks":checks}


def _2600_external_task(instruction: str, operator_token: str, approved: bool) -> Dict[str, Any]:
    try:
        plan = _plan_200(instruction)
    except Exception as exc:
        return {"status":"blocked","reason":"external planning failed safely","error":str(exc)[:400]}
    missing = list(plan.get("missing_dependencies") or [])
    if missing:
        return {"status":"awaiting_connection","missing_dependencies":missing,"plan":plan,"external_action_executed":False}
    if (plan.get("approval_required") or plan.get("operator_gate_required")) and not approved:
        return {"status":"awaiting_approval","approval_required":True,"plan":plan,"external_action_executed":False}
    body = {"objective":instruction,"approved":bool(approved),"operator_token":operator_token}
    try:
        live = agent_execute_200(body)
        return {"status":live.get("status","completed"),"result":live,"plan":plan,"external_action_executed":live.get("status") in {"queued","completed","verified","accepted"}}
    except Exception as exc:
        return {"status":"failed_closed","error":str(exc)[:500],"plan":plan,"automatic_uncertain_replay":False}


def _2600_execute_task(task: Dict[str, Any], mission_id: str, operator_token: str, approved: bool) -> Dict[str, Any]:
    kind = str(task.get("kind") or "general")
    instruction = str(task.get("instruction") or "").strip()
    started = _2600_now()
    attempts = 0
    max_attempts = 2 if kind not in {"external_action"} else 1
    last_error = None
    for attempt in range(1, max_attempts + 1):
        attempts = attempt
        try:
            if kind == "research":
                result = _2600_public_research(instruction, mission_id)
            elif kind == "customer_discovery":
                result = _2600_customer_discovery(instruction, mission_id)
            elif kind == "opportunity_discovery":
                result = _f2300_economic_engine({"problem":instruction})
            elif kind == "offer_factory":
                result = _2600_offer_factory(instruction, mission_id)
            elif kind == "distribution":
                result = _2600_distribution_factory(instruction, mission_id)
            elif kind == "media":
                result = _2600_media_factory(instruction, mission_id)
            elif kind == "free_resource":
                result = _2600_free_resource_factory(instruction, mission_id)
            elif kind == "external_action":
                result = _2600_external_task(instruction, operator_token, approved)
            elif kind == "memory":
                text_value = re.sub(r"^.*?\b(?:remember|memorize|save this)\b", "", instruction, flags=re.I).strip() or instruction
                mid = _uid2110("memory")
                with _DB_LOCK_2110, _db2110() as c:
                    c.execute(
                        "INSERT INTO infinity_memory_2110(memory_id,user_id,kind,text,confidence,provenance_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",
                        (mid,"default","explicit",text_value[:10000],1.0,_json_2110.dumps({"mission_id":mission_id,"source":"2600"}),_now2110(),_now2110()),
                    )
                result = {"status":"completed","memory_id":mid,"remembered":text_value,"truthful":True}
            elif kind == "artifact":
                result = {"status":"completed","artifact":_2600_write_artifact(mission_id,"mission_artifact",instruction[:240] or "mission artifact", "# AI Infinity 2600 Artifact\n\nObjective\n\n" + instruction + "\n\nAcceptance\n\nDefine measurable outcome, provenance, verification and owner review before consequential use.\n")}
            elif kind == "learning":
                result = _2600_learning_capture(mission_id,"Successful work should become a reusable procedure only after evidence and benchmark review.", {"instruction":instruction})
            else:
                context = [{"role":"user","content":instruction}]
                answer, provider, errors = _model_call2110(context, system="You are AI Infinity 2600. Produce factual useful work. Never claim external actions, customers, money, or outcomes that were not actually verified by the execution layer.")
                result = {"status":"completed","answer":answer or _builtin_chat2110(instruction),"model_provider":provider,"model_errors":errors,"truthful":True}
            result = dict(result or {})
            result.setdefault("truthful", True)
            result.setdefault("automatic_uncertain_replay", False)
            result["latency_ms"] = int((_2600_now() - started) * 1000)
            quality = _2600_quality(result)
            result["quality"] = quality
            if result.get("status") in {"completed","completed_verified","queued","accepted","verified","awaiting_approval","awaiting_connection","planned"}:
                return {"status":result.get("status"),"result":result,"attempts":attempts,"recovery_attempts":max(0,attempts-1)}
            last_error = str(result.get("error") or "task returned non-closed state")
            if attempt >= max_attempts: break
        except Exception as exc:
            last_error = str(exc)[:500]
            if attempt >= max_attempts: break
            if kind == "external_action": break
    return {"status":"failed_closed","result":{"error":last_error or "unknown failure","truthful":True,"automatic_uncertain_replay":False},"attempts":attempts,"recovery_attempts":max(0,attempts-1)}


def _2600_build_plan(objective: str, user_id: str = "default") -> Dict[str, Any]:
    parts = _2600_split_objective(objective)
    if not parts:
        raise HTTPException(400,"objective is required")
    try:
        base_plan = _plan_200(objective)
    except Exception:
        base_plan = {"missing_dependencies":[],"approval_required":False,"operator_gate_required":False}
    tasks=[]
    seen=set()
    ordinal=0
    for part in parts:
        kinds=_2600_classify_instruction(part)
        # Generic value-building commands benefit from the full safe production loop.
        if len(parts)==1 and any(x in part.lower() for x in ("build", "launch", "grow", "business", "make money", "value")):
            kinds=[x for x in ["research","customer_discovery","opportunity_discovery","offer_factory","distribution","media","free_resource","artifact","learning"] if x not in kinds] + kinds
        for kind in kinds:
            key=f"{kind}:{_2600_slug(part,60)}"
            if key in seen: continue
            seen.add(key); ordinal += 1
            safe = 0 if kind == "external_action" else 1
            tasks.append({"ordinal":ordinal,"task_key":key,"kind":kind,"instruction":part[:6000],"safe_to_execute":bool(safe)})
    # Final synthesis always closes the loop around the actual outputs.
    ordinal += 1
    tasks.append({"ordinal":ordinal,"task_key":"synthesis:final","kind":"artifact","instruction":f"Create the mission completion package for: {objective}","safe_to_execute":True})
    return {
        "objective":objective,
        "user_id":user_id,
        "tasks":tasks[:40],
        "base_external_plan":base_plan,
        "execution_policy":{
            "safe_tasks_execute_immediately":True,
            "external_side_effects_require_approval":True,
            "external_dependencies_must_be_live":True,
            "uncertain_side_effect_replay":False,
            "arbitrary_code_execution":False,
            "money_movement_without_approval":False,
        },
        "plan_hash":_2600_digest(tasks),
        "truthful":True,
    }


