        {"capability":"GitHub","ready":provider_ready.get("github",False),"requires_connection":True,"entry":"/integration/execute"},
        {"capability":"Slack","ready":provider_ready.get("slack",False),"requires_connection":True,"entry":"/integration/execute"},
