@app.post("/infinity/2600/start")
def _f2600_start(payload: Dict[str, Any]):
    objective=str(payload.get("objective") or payload.get("command") or "").strip()
    user_id=str(payload.get("user_id") or "default").strip()[:200] or "default"
    mode=str(payload.get("mode") or "execute").strip().lower()
    approved=bool(payload.get("approved"))
    operator_token=str(payload.get("operator_token") or "")
    plan=_2600_build_plan(objective,user_id)
    mission_id=_2600_create_mission(objective,user_id,mode,plan)
    if mode in {"plan","simulate","dry-run"}:
        with _DB_LOCK_2110, _db2110() as c:
            c.execute("UPDATE ai2600_missions SET status='planned',updated_at=? WHERE mission_id=?",(_2600_now(),mission_id))
        return {"status":"planned" if mode=="plan" else "simulated","version":FINAL2600_VERSION,"mission_id":mission_id,"plan":plan,"external_side_effects_executed":False,"truthful":True}
    result=_2600_run_mission(mission_id,approved=approved,operator_token=operator_token)
    return {"status":result["status"],"version":FINAL2600_VERSION,"mission_id":mission_id,"result":result,"truthful":True}


