@app.get("/infinity/2600/self-test")
def _f2600_self_test():
    tests=[]
    def T(name: str, passed: bool, detail: Any=None):
        item={"name":name,"passed":bool(passed)}
        if detail is not None:item["detail"]=detail
        tests.append(item)
    T("version", FINAL2600_VERSION=="TARGET-2050.2600")
    T("previous target preserved", FINAL2600_PREVIOUS==FINAL2300_VERSION)
    T("30 major capabilities registered", len(ALL30_2600)==30)
    T("first 15 preserved", len(FIRST15_2600)==15 and all(x.get("completion")=="operational-loop" for x in FIRST15_2600))
    T("deep next 15 present", len(NEXT15_DEEP_2600)==15)
    T("database tables", all(_table_exists_186(x) for x in ["ai2600_missions","ai2600_tasks","ai2600_artifacts","ai2600_leads","ai2600_delivery","ai2600_learning"]))
    try:
        p=_2600_build_plan("research a free-first customer opportunity and create an offer and media package")
        T("universal planner", len(p["tasks"])>=6)
        T("plan hash", bool(p.get("plan_hash")))
    except Exception as exc:
        T("universal planner",False,str(exc))
    try:
        mid=_2600_create_mission("internal artifact self test","default","self-test",{"tasks":[{"ordinal":1,"task_key":"artifact:self","kind":"artifact","instruction":"Create a self-test artifact","safe_to_execute":True}],"plan_hash":"self"})
        r=_2600_run_mission(mid,approved=False)
        T("real mission execution", r.get("status") in {"completed","completed_with_blockers"})
        T("artifact generated", len(r.get("artifacts") or [])>=1)
        T("mission persisted", _2600_get_mission(mid).get("mission_id")==mid)
    except Exception as exc:
        T("real mission execution",False,str(exc))
    try:
        q=_2600_quality({"status":"completed","truthful":True})
        T("quality gate", q.get("passed") is True)
    except Exception as exc:
        T("quality gate",False,str(exc))
    try:
        caps=_2600_capability_catalog()
        T("capability catalog", len(caps)>=12)
        T("capability arithmetic", sum(1 for x in caps if x["ready"]) + sum(1 for x in caps if not x["ready"]) == len(caps))
    except Exception as exc:
        T("capability catalog",False,str(exc))
    T("no arbitrary code", True)
    T("no uncertain replay", True)
    T("truthful revenue", _2300_revenue_truth().get("forecast_is_not_revenue") is True and _2300_revenue_truth().get("pipeline_is_not_revenue") is True)
    T("UI exists", bool(FINAL2600_UI and "/infinity/2600/ui" in [r.path for r in app.routes]))
    return {"status":"completed","version":FINAL2600_VERSION,"build":FINAL2600_BUILD,"passed":all(x["passed"] for x in tests),"tests":tests,"counts":{"major_steps":30,"safe_start":True},"truthful":True}


