# ---------------------------------------------------------------------------
# 2600.1 practical hardening: direct URL research + workforce dispatch.
# ---------------------------------------------------------------------------

def _2600_public_research_direct(objective: str, mission_id: str, limit: int = 8) -> Dict[str, Any]:
    explicit = re.findall(r"https?://[^\s)\]>]+", str(objective or ""))
    explicit = [u.rstrip(".,;:") for u in explicit[:4]]
    safe_explicit=[]
    for u in explicit:
        try:
            if _safe_public_url2110(u): safe_explicit.append(u)
        except Exception:
            pass
    discovered = _discover2110(objective, max(4, min(int(limit), 8)))
    sources = list(discovered.get("sources") or [])[:8]
    known={str(x.get("url")) for x in sources}
    for u in safe_explicit:
        if u not in known:
            parsed=urlparse(u)
            sources.insert(0,{"url":u,"domain":parsed.netloc,"title":u,"source_family":"explicit-url","relevance":1.0})
    sources=sources[:8]
    evidence=[]; errors=[]
    def fetch_one(src):
        u=str(src.get("url") or "")
        try:
            f=_fetch_evidence2110(u)
            return {"ok":True,"source":src,"fetch":f}
        except Exception as exc:
            return {"ok":False,"source":src,"error":str(exc)[:300]}
    with _cf_2300.ThreadPoolExecutor(max_workers=min(6,max(1,len(sources)))) as ex:
        futures=[ex.submit(fetch_one,s) for s in sources]
        for fut in _cf_2300.as_completed(futures):
            r=fut.result()
            if r.get("ok"):
                src=r["source"]; f=r["fetch"]
                item={"url":src.get("url"),"domain":src.get("domain"),"title":src.get("title") or src.get("url"),"source_family":src.get("source_family"),"relevance":src.get("relevance"),"excerpt":str(f.get("text") or "")[:1800],"content_hash":f.get("hash"),"http_status":f.get("status")}
                evidence.append(item)
                try:
                    eid=_uid2110("evidence")
                    with _DB_LOCK_2110,_db2110() as c:
                        c.execute("INSERT INTO infinity_evidence_2110(evidence_id,mission_id,user_id,url,domain,title,excerpt,source_family,retrieved_at,content_hash,relevance) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(eid,mission_id,"default",item["url"],item["domain"],item["title"],item["excerpt"],item.get("source_family"),_now2110(),item.get("content_hash"),float(item.get("relevance") or 0.5)))
                except Exception:
                    pass
            else:
                errors.append({"url":r["source"].get("url"),"error":r.get("error")})
    domains=sorted({str(x.get("domain")) for x in evidence if x.get("domain")})
    return {"status":"completed","query":objective,"explicit_urls":safe_explicit,"discovery":discovered,"evidence":sorted(evidence,key=lambda x:(str(x.get("domain")),str(x.get("url")))),"errors":errors,"evidence_count":len(evidence),"independent_domains":len(domains),"verified":len(evidence)>=2 and len(domains)>=2,"verification_basis":"two independent fetched domains" if len(evidence)>=2 and len(domains)>=2 else "not enough independent evidence"}

_2600_public_research = _2600_public_research_direct


def _2600_workforce_dispatch(objective: str, mission_id: str) -> Dict[str, Any]:
    text_value=str(objective or "").lower()
    mapping=[]
    role_rows=[]
    with _DB_LOCK_2110,_db2110() as c:
        role_rows=[dict(r) for r in c.execute("SELECT role_id,department,name,specialization,capacity,status FROM ai2300_role_registry WHERE org_id=? AND status='active' ORDER BY department,name",(AI_INFINITY_2275_ORG_ID,)).fetchall()]
    keywords=[x for x in re.findall(r"[a-zA-Z]{4,}",text_value)]
    for role in role_rows:
        score=0
        words=(role["name"]+" "+role["specialization"]+" "+role["department"]).lower().split()
        score += sum(1 for k in keywords if k in words)
        if role["department"].lower() in text_value: score += 2
        if score>0: mapping.append((score,role))
    mapping=sorted(mapping,key=lambda x:(x[0],x[1]["name"]),reverse=True)[:8]
    if not mapping and role_rows:
        preferred=[r for r in role_rows if r["role_id"] in {"chief-of-staff","operations-manager","principal-engineer"}]
        mapping=[(0,r) for r in preferred[:3]]
    return {"status":"completed","mission_id":mission_id,"assignments":[{"role_id":r["role_id"],"role":r["name"],"department":r["department"],"specialization":r["specialization"],"capacity":r["capacity"],"match_score":s,"human_or_agent_identity_verified":False} for s,r in mapping],"actual_humans_created":False,"truthful":True}


def _2600_execute_task_with_workforce(task: Dict[str,Any], mission_id: str, operator_token: str, approved: bool) -> Dict[str,Any]:
    if str(task.get("kind"))=="workforce":
        return {"status":"completed","result":_2600_workforce_dispatch(task.get("instruction") or "",mission_id),"attempts":1,"recovery_attempts":0}
    return _2600_original_execute_task(task,mission_id,operator_token,approved)

_2600_original_execute_task = _2600_execute_task
_2600_execute_task = _2600_execute_task_with_workforce


def _2600_classifier_with_workforce(instruction: str) -> List[str]:
    kinds=_2600_classify_instruction.__wrapped__(instruction) if hasattr(_2600_classify_instruction,"__wrapped__") else _2600_classify_instruction(instruction)
    q=str(instruction or "").lower()
    if any(x in q for x in ("workforce","team","assign roles","specialists","agents","delegate work")) and "workforce" not in kinds:
        kinds.append("workforce")
    return kinds
# Keep the existing classifier for compatibility and apply a small explicit augmentation.
_2600_classify_instruction_base = _2600_classify_instruction
_2600_classify_instruction = lambda instruction: sorted(set(_2600_classify_instruction_base(instruction)+(["workforce"] if any(x in str(instruction or "").lower() for x in ("workforce","team","assign roles","specialists","agents","delegate work")) else [])), key=lambda x:["research","customer_discovery","opportunity_discovery","offer_factory","distribution","media","free_resource","external_action","memory","artifact","learning","workforce","general"].index(x) if x in ["research","customer_discovery","opportunity_discovery","offer_factory","distribution","media","free_resource","external_action","memory","artifact","learning","workforce","general"] else 99)

# Re-wrap the planner after the classifier augmentation so future starts see workforce dispatch.
_2600_build_plan_base = _2600_build_plan
def _2600_build_plan(objective: str, user_id: str = "default") -> Dict[str,Any]:
    plan=_2600_build_plan_base(objective,user_id)
    for i,t in enumerate(plan.get("tasks",[]),1): t["ordinal"]=i
    plan["tasks"]=plan.get("tasks",[])[:40]
    plan["plan_hash"]=_2600_digest(plan["tasks"])
    return plan


